require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\SpecialCategoryRecoveryService;
Auth::requireSuperAdmin();$pdo=Database::connection();SpecialCategoryRecoveryService::ensureSchema($pdo);$auditPreview=SpecialCategoryRecoveryService::recoverManualAssignments($pdo,false);$backups=SpecialCategoryRecoveryService::availableBackups();$preview=null;$dataEntryPreview=null;$message='';$error='';$type='';$name='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Csrf::verify($_POST['_csrf']??null))$error='Invalid security token.';
 else try{
  $action=(string)($_POST['action']??'preview_backup');
  if($action==='preview_data_entry'){
   foreach(['amateur_csv','open_csv'] as $field){if(!isset($_FILES[$field])||!is_uploaded_file((string)$_FILES[$field]['tmp_name'])||(int)$_FILES[$field]['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Upload both official Google Forms CSV exports.');if((int)$_FILES[$field]['size']>5*1024*1024)throw new RuntimeException('Each data-entry CSV must be 5 MB or smaller.');}
   $manifest=SpecialCategoryRecoveryService::dataEntryManifest((string)$_FILES['amateur_csv']['tmp_name'],(string)$_FILES['open_csv']['tmp_name']);$_SESSION['special_category_data_entry_manifest']=$manifest;$dataEntryPreview=SpecialCategoryRecoveryService::previewDataEntryManifest($pdo,$manifest);
  }elseif($action==='restore_data_entry'){
   if(strtoupper(trim((string)($_POST['confirmation']??'')))!=='RESTORE DATA ENTRY CATEGORIES')throw new RuntimeException('Type RESTORE DATA ENTRY CATEGORIES to confirm.');$manifest=$_SESSION['special_category_data_entry_manifest']??[];if(!is_array($manifest)||$manifest===[])throw new RuntimeException('The data-entry preview expired. Upload both CSV exports again.');$result=SpecialCategoryRecoveryService::restoreDataEntryManifest($pdo,$manifest,(int)(Auth::user()['id']??0));Auth::audit((int)(Auth::user()['id']??0),'special_category_data_entry_recovery',$result,'competitor_recovery',null);$message=$result['restored'].' verified data-entry assignments restored. Safety backup: '.$result['safety_backup'].'.';$dataEntryPreview=SpecialCategoryRecoveryService::previewDataEntryManifest($pdo,$manifest);
  }else{
  $type=(string)($_POST['backup_type']??'');$name=(string)($_POST['backup_name']??'');$key=(string)($_POST['backup_key']??'');if(($type===''||$name==='')&&str_contains($key,'|'))[$type,$name]=explode('|',$key,2);
  if($action==='restore_backup'){
   if(strtoupper(trim((string)($_POST['confirmation']??'')))!=='RESTORE SPECIAL CATEGORIES')throw new RuntimeException('Type RESTORE SPECIAL CATEGORIES to confirm.');
   $result=SpecialCategoryRecoveryService::restoreFromBackup($pdo,$type,$name,(int)(Auth::user()['id']??0));Auth::audit((int)(Auth::user()['id']??0),'special_category_backup_recovery',$result,'competitor_recovery',null);$message=$result['restored'].' remaining Special Category assignments restored. Safety backup: '.$result['safety_backup'].'.';
  }
  $preview=SpecialCategoryRecoveryService::previewBackup($pdo,$type,$name);
  }
 }catch(Throwable $e){$error=$e->getMessage();}
}
$rows=$pdo->query("SELECT r.*,c.bdc_id,c.exact_name FROM bdc_special_category_recovery r JOIN bdc_competitors c ON c.id=r.competitor_id ORDER BY r.applied_at IS NULL,r.applied_at DESC,r.id DESC")->fetchAll();
