<div class="table-responsive" style="max-height:520px"><table class="table table-sm"><thead><tr><th>Submitted name</th><th>Matched competitor</th><th>Dance</th><th>Current</th><th>Expected</th><th>Source</th><th>Status</th></tr></thead><tbody><?php foreach($dataEntryPreview['candidates'] as $candidate):?><tr><td><?=e($candidate['name'])?></td><td><?=e(($candidate['bdc_id']??'').' '.($candidate['matched_name']??'—'))?></td><td><?=e(ucfirst($candidate['dance_style']))?></td><td><?=e(ucwords(str_replace('_',' ',$candidate['current_category']?:'—')))?></td><td><?=e(ucwords(str_replace('_',' ',$candidate['category'])))?></td><td><?=e(ucfirst($candidate['source']))?></td><td><?=e(ucwords(str_replace('_',' ',$candidate['status'])))?></td></tr><?php endforeach;?></tbody></table></div></div></section><?php endif;?>
