<div class="table-responsive" style="max-height:460px"><table class="table table-sm"><thead><tr><th>BDC ID</th><th>Competitor</th><th>Dance</th><th>Current</th><th>Backup</th><th>Status</th></tr></thead><tbody><?php foreach($preview['candidates'] as $candidate):?><tr><td><code><?=e($candidate['bdc_id']?:'Legacy #'.$candidate['backup_competitor_id'])?></code></td><td><?=e($candidate['exact_name'])?></td><td><?=e(ucfirst($candidate['dance_style']))?></td><td><?=e($candidate['current_category']?ucwords(str_replace('_',' ',$candidate['current_category'])):'—')?></td><td><?=e(ucwords(str_replace('_',' ',$candidate['category'])))?></td><td><?php if(!$candidate['competitor_id']):?><span class="badge text-bg-danger">Missing</span><?php elseif($candidate['needs_restore']):?><span class="badge text-bg-warning">Restore</span><?php else:?><span class="badge text-bg-success">Already correct · skipped</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></section><?php endif;?>
